#!/usr/bin/env python3
"""Generate src/iana/{registered,assigned}.rs from the pinned registry snapshot.

Inputs (both in this directory):
  kerberos-parameters-2024-12-06.txt  the IANA "Kerberos Parameters" registry, TXT form, Last Updated 2024-12-06
  assigned-numbers.tsv                message, name, address, authorization-data types and error codes read from
                                      MIT krb5 1.22.2 (src/include/krb5/krb5.hin, src/lib/krb5/error_tables/krb5_err.et)
                                      plus the RFC 4120 values MIT does not define (provenance column)
Usage: python3 generate.py <repository root>; then format the output with `rustfmt --edition 2024 src/iana/*.rs`.
"""
import re
import sys
import unicodedata
from pathlib import Path

HERE = Path(__file__).resolve().parent
TXT = (HERE / "kerberos-parameters-2024-12-06.txt").read_text(encoding="utf-8").split("\n")


def section(title, stop):
    start = next(i for i, line in enumerate(TXT) if line.strip() == title and i > 30)
    end = next(i for i, line in enumerate(TXT) if i > start and line.strip() == stop)
    return TXT[start:end]


def rows(lines, split):
    found = []
    for line in lines:
        m = re.match(r"^\s*(-?\d+)(\s+.*)?$", line)
        if not m or not m.group(2):
            continue
        number = int(m.group(1))
        body = m.group(2).strip()
        parts = re.split(r"\s{2,}", body) if split == "wide" else body.split(None, 1)[:1] + [""]
        name = parts[0].strip()
        reference = ""
        for part in re.split(r"\s{2,}", body):
            if part.startswith("["):
                reference = part.split(";")[0].strip()
        if not name or name.lower().startswith(("unassigned", "reserved")) or name.startswith("["):
            continue
        found.append((number, name, reference))
    return found


def const_name(name):
    base = re.sub(r"\s*\((?:deprecated|unkeyed)\)", lambda m: "_UNKEYED" if "unkeyed" in m.group(0) else "", name)
    base = re.sub(r"[^A-Za-z0-9]+", "_", base).strip("_").upper()
    return base if not base[0].isdigit() else "N" + base


def hexlit(n):
    return str(n) if -256 < n < 256 else (f"0x{n:04X}" if n >= 0 else str(n))


def literal(n):
    if n < 0 or n < 256:
        return f"{n}_i32"
    digits = f"{n:X}"
    if len(digits) > 4:
        digits = "_".join([digits[: len(digits) % 4 or 4]] + [digits[i : i + 4] for i in range((len(digits) % 4 or 4), len(digits), 4)])
    return f"0x{digits}_i32"


def emit(title, module, entries, kind_doc, source):
    """The text of src/iana/<module>.rs: one named constant per entry and the table."""
    seen = {}
    lines = [
        f"//! {title}.",
        "//!",
        f"//! {source}",
        "//! Generated by `tests/fixtures/iana/generate.py`; do not edit by hand.",
        "// allow: SIZE_OK - generated data table",
        "",
        "use super::{Entry, Registry};",
        "",
    ]
    table = []
    for number, name, reference in entries:
        const = const_name(name)
        if const in seen:
            const = f"{const}_{number}"
        seen[const] = number
        deprecated = "deprecated" in name.lower()
        clean = re.sub(r"\s*\(deprecated\)", "", name)
        ref = unicodedata.normalize("NFKD", reference.strip("[]")).encode("ascii", "ignore").decode("ascii")
        lines.append(f"/// `{clean}` ({number}).")
        lines.append(f"pub const {const}: i32 = {literal(number)};")
        table.append((const, number, clean, ref, deprecated))
    lines.append("")
    lines.append(f"/// {kind_doc}")
    lines.append("pub const REGISTRY: Registry = Registry::new(")
    lines.append(f'    "{title}",')
    lines.append("    &[")
    for const, number, clean, ref, deprecated in table:
        lines.append(f'        Entry::new({const}, "{clean}", "{ref}", {"true" if deprecated else "false"}),')
    lines.append("    ],")
    lines.append(");")
    return "\n".join(lines) + "\n"


IANA = "Source: the IANA Kerberos Parameters registry, Last Updated 2024-12-06."
MIT = "Source: MIT krb5 1.22.2 (`krb5.hin`, `krb5_err.et`) and RFC 4120; IANA hosts no registry for these numbers."
MODULES = []


def registered():
    spec = [
        ("Kerberos encryption type numbers", "encryption_type", "Kerberos Encryption Type Numbers", "Kerberos Checksum Type Numbers", "wide"),
        ("Kerberos checksum type numbers", "checksum_type", "Kerberos Checksum Type Numbers", "Kerberos TCP Extensions", "wide"),
        ("Kerberos pre-authentication and typed data types", "padata_type", "Pre-authentication and Typed Data", "FAST Armor Types", "wide"),
        ("FAST armor types", "fast_armor_type", "FAST Armor Types", "FAST Options", "word"),
        ("FAST options", "fast_option", "FAST Options", "Well-Known Kerberos Principal Names", "word"),
        ("Kerberos message transport types", "transport_type", "Kerberos Message Transport Types", "Kerberos Second Factor Types", "wide"),
        ("Kerberos second factor types", "second_factor_type", "Kerberos Second Factor Types", "Kerberos SPAKE Groups", "wide"),
    ]
    files = {}
    for title, module, head, stop, split in spec:
        files[module] = emit(title, module, rows(section(head, stop), split), "Every assigned number of the registry.", IANA)
    spake = [(1, "edwards25519", "RFC 9588"), (2, "P-256", "RFC 9588"), (3, "P-384", "RFC 9588"), (4, "P-521", "RFC 9588")]
    files["spake_group"] = emit("Kerberos SPAKE groups", "spake_group", [(n, nm, f"[{r}]") for n, nm, r in spake], "Every assigned number of the registry.", IANA)
    return files


def assigned():
    kinds = {
        "message": ("Kerberos message types (RFC 4120 section 5.4.1)", "message_type", "", ""),
        "name": ("Kerberos principal name types (RFC 4120 section 6.2)", "name_type", "", "NT_"),
        "address": ("Kerberos address types (RFC 4120 section 7.5.3)", "address_type", "", "ADDRTYPE_"),
        "authdata": ("Kerberos authorization data types (RFC 4120 section 5.2.6)", "authorization_data_type", "", "AUTHDATA_"),
        "error": ("Kerberos error codes (RFC 4120 section 7.5.9)", "error_code", "", ""),
    }
    data = {k: [] for k in kinds}
    for line in (HERE / "assigned-numbers.tsv").read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or not line.strip():
            continue
        kind, number, name, source = line.split("\t")
        strip = kinds[kind][3]
        name = name[len(strip):] if strip and name.startswith(strip) else name
        data[kind].append((int(number), name, source))
    files = {}
    for kind, (title, module, prefix, _strip) in kinds.items():
        entries = [
            (n, prefix + nm, f"[MIT krb5_err.et 1.22.2: {src}]" if kind == "error" else f"[{src}]")
            for n, nm, src in sorted(data[kind])
        ]
        files[module] = emit(title, module, entries, "Every assigned number.", MIT)
    return files


root = Path(sys.argv[1])
(root / "src/iana").mkdir(parents=True, exist_ok=True)
for module, text in {**registered(), **assigned()}.items():
    (root / f"src/iana/{module}.rs").write_text(text, encoding="utf-8")
